INSERT INTO purpose VALUES('theory-dynamic-graphs','maintenance::AcyclicityMaintenance','struct','Holds a directed graph whose topological order is maintained under edge insertion, so the order''s state is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-dynamic-graphs','maintenance::AdmittedEdgeCount','struct','Names the number of edges an `AcyclicityMaintenance` currently holds, so the count''s value is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-dynamic-graphs','maintenance::EdgeVerdict','enum','Names the verdict on one offered edge, so the verdict''s kind is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-dynamic-graphs','maintenance::InsertionCount','struct','Names the number of edge insertions offered to an `AcyclicityMaintenance`, so the count''s value is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-dynamic-graphs','maintenance::MaintenanceError','enum','Names a failure of an `AcyclicityMaintenance` operation, so the failure''s cause is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-dynamic-graphs','maintenance::MaintenanceTelemetry','struct','Holds the work an `AcyclicityMaintenance` has performed since construction, so the work''s counters are read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-dynamic-graphs','maintenance::RefusalCount','struct','Names the number of insertions refused because they would close a cycle, so the count''s value is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-dynamic-graphs','maintenance::RelocationCount','struct','Names the number of nodes moved within the maintained order, so the count''s value is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-dynamic-graphs','maintenance::RepairCount','struct','Names the number of insertions that ran against the standing order and were repaired, so the count''s value is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-dynamic-graphs','maintenance::TopologicalOrderStatus','struct','Names whether the maintained order is a topological order of the admitted edges, so the status''s verdict is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-dynamic-graphs','maintenance::VisitCount','struct','Names the number of nodes the bounded searches have reached, so the count''s value is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-dynamic-graphs','potential::AdmittedConstraintCount','struct','Names the number of constraints a `PotentialMaintenance` currently holds, so the count''s value is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-dynamic-graphs','potential::ConstraintVerdict','enum','Names the verdict on one offered constraint, so the verdict''s kind is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-dynamic-graphs','potential::FeasibilityStatus','struct','Names whether the standing valuation satisfies every admitted constraint, so the status''s verdict is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-dynamic-graphs','potential::Offset','struct','Names the integer offset a constraint carries, so the offset''s value is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-dynamic-graphs','potential::Potential','struct','Names a node''s standing value in the maintained valuation, so the value''s magnitude is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-dynamic-graphs','potential::PotentialAbsence','enum','Names why a potential lookup has no value, so the absence''s cause is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-dynamic-graphs','potential::PotentialError','enum','Names a failure of a `PotentialMaintenance` operation, so the failure''s cause is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-dynamic-graphs','potential::PotentialMaintenance','struct','Holds a constraint system whose valuation is maintained under constraint insertion, so the valuation''s state is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-dynamic-graphs','potential::PotentialTelemetry','struct','Holds the work a `PotentialMaintenance` has performed since construction, so the work''s counters are read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-dynamic-graphs','potential::RaiseCount','struct','Names the number of value raises the propagation has performed, so the count''s value is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-dynamic-graphs','potential::RefutationCount','struct','Names the number of offers refused as unsatisfiable, so the count''s value is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-dynamic-graphs','potential::RelaxationCount','struct','Names the number of constraints the propagation has examined, so the count''s value is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('theory-dynamic-graphs','slot::SlotIndex','struct','Names a dense vector position holding one node''s per-node state, so the position''s index is read.',NULL,'fits','sound',NULL);
